parameters.jsCode:
const item = $input.first().json;

// Handle both nested object and flat string formats
const senderName = item.from?.emailAddress?.name || 
                   item.from?.name ||
                   item.sender?.emailAddress?.name ||
                   item.from?.split('@')[0] ||
                   "";

const senderEmail = item.from?.emailAddress?.address || 
                    item.from?.address ||
                    item.sender?.emailAddress?.address ||
                    (typeof item.from === 'string' ? item.from : "") ||
                    "";

const bodyText = item.body?.content || 
                 item.bodyPreview || 
                 "";

const subject = item.subject || "";
const messageId = item.id || "";
const conversationId = item.conversationId || "";

return [{
  json: {
    senderName,
    senderEmail,
    bodyText,
    subject,
    messageId,
    conversationId
  }
}];

